      { text: 'Apply a condition to filter products with at least 3 unique buyers. Use the appropriate clause to enforce this requirement.', starterCode: 'SELECT oi.product_id, COUNT(DISTINCT o.user_id) AS unique_buyers\nFROM order_items oi\nJOIN orders o ON oi.order_id = o.order_id\nGROUP BY oi.product_id\n-- add filter condition here' }
