      { text: 'Ensure that the completed order occurs after the return and filter for the correct statuses. Use conditions to link these two events in time.', starterCode: 'SELECT DISTINCT u.email, u.user_id\nFROM users u\nJOIN orders o1 ON u.user_id = o1.user_id AND o1.status = \'returned\'\nJOIN orders o2 ON u.user_id = o2.user_id AND o2.status = \'completed\'\n  AND o2.created_at > o1.created_at' }
