      { text: 'Focus on identifying the last interaction date for each user. Consider how to aggregate this information and calculate the days since the reference date.', starterCode: 'WITH last_interaction AS (\n  SELECT user_id, MAX(occurred_at) AS last_interaction_date\n  FROM interactions\n  GROUP BY user_id\n)\nSELECT u.user_id, u.username, li.last_interaction_date,\n       -- calculate days_since_last here\nFROM users u\nJOIN last_interaction li ON u.user_id = li.user_id' },
      { text: 'Use the reference date \'2023-12-06\' to compute the days since the last interaction. Think about how to subtract dates and convert the result to an integer.', starterCode: 'WITH last_interaction AS (\n  SELECT user_id, MAX(occurred_at) AS last_interaction_date\n  FROM interactions\n  GROUP BY user_id\n)\nSELECT u.user_id, u.username, li.last_interaction_date,\n       CAST(julianday(\'2023-12-06\') - julianday(li.last_interaction_date) AS INTEGER) AS days_since_last\nFROM users u\nJOIN last_interaction li ON u.user_id = li.user_id\nORDER BY days_since_last DESC' }
