      { text: 'Think about how to differentiate between total headcount and active headcount in your query.', starterCode: 'SELECT d.name AS dept_name, COUNT(e.emp_id) AS total_headcount, SUM(CASE WHEN e.is_active = 1 THEN 1 ELSE 0 END) AS active_headcount FROM departments d LEFT JOIN employees e ON d.dept_id = e.dept_id GROUP BY d.name;' },
      { text: 'Ensure that your query accounts for all employees in each department, including those who may have been inactive.', starterCode: 'SELECT d.name AS dept_name, COUNT(e.emp_id) AS total_headcount, SUM(CASE WHEN e.is_active = 1 THEN 1 ELSE 0 END) AS active_headcount FROM departments d LEFT JOIN employees e ON d.dept_id = e.dept_id GROUP BY d.name ORDER BY d.name;' },
      { text: 'Verify that your query correctly groups the results by department name and returns one row per department.', starterCode: 'SELECT d.name AS dept_name, COUNT(e.emp_id) AS total_headcount, SUM(CASE WHEN e.is_active = 1 THEN 1 ELSE 0 END) AS active_headcount FROM departments d LEFT JOIN employees e ON d.dept_id = e.dept_id GROUP BY d.name ORDER BY d.name;' },
      { text: 'Double-check that your query returns the correct counts for both total and active headcount per department.', starterCode: 'SELECT d.name AS dept_name, COUNT(e.emp_id) AS total_headcount, SUM(CASE WHEN e.is_active = 1 THEN 1 ELSE 0 END) AS active_headcount FROM departments d LEFT JOIN employees e ON d.dept_id = e.dept_id GROUP BY d.name ORDER BY d.name;' }
