    priority: 1,
    estimatedMin: 5,
    datamartId: 'fintech',
    prompt: 'The compliance team at Stripe needs to identify open disputes that are not being displayed in their dashboard. Return dispute-related information including the merchant name, transaction ID, and dispute status, handling any NULL values in the dispute status appropriately so open disputes are not dropped.',
    brokenQueryReturnsZeroRows: true,
    brokenQuery: 'SELECT dispute_id, amount, opened_at\nFROM disputes\nWHERE resolved_at = NULL\nORDER BY amount DESC',
    brokenOutputNote: 'Returns 0 rows. The compliance team sees an empty queue, assumes everything is resolved, and closes the review cycle. Three real disputes sit unreviewed — including a $3,500 fraud claim.',
