    brokenQuery: 'SELECT s.name,\n  ROUND(SUM(t.sale_price), 2) AS total_gmv\nFROM sellers s\nJOIN transactions t ON s.seller_id = t.seller_id\nWHERE t.status = \'completed\'\nGROUP BY s.seller_id, s.name\nORDER BY total_gmv DESC',
