    title: 'Seller Activity Rate — Survivorship Bias Excludes No-Sale Sellers',
    company: 'Etsy',
    companyDomain: 'etsy.com',
    format: 'forensic',
    difficulty: 'Forensic',
    isFree: false,
    tags: ['forensic', 'survivorship bias', 'marketplace', 'denominator error', 'INNER vs LEFT JOIN', 'bug-fix'],
    roles: ['PA', 'DA', 'PM'],
    priority: 1,
    estimatedMin: 9,
    datamartId: 'marketplace',
    prompt: 'The Etsy growth team needs to identify why their report shows an average of 2.6 completed transactions per seller, but some sellers managed by a success manager have zero transactions. The query should return the average number of completed transactions per seller, along with the count of sellers with zero transactions. Ensure the query accounts for all sellers, including those with no completed transactions.',
    brokenQuery: 'SELECT ROUND(AVG(seller_txns), 1) AS avg_completed_txns\nFROM (\n  SELECT seller_id, COUNT(*) AS seller_txns\n  FROM transactions\n  WHERE status = \'completed\'\n  GROUP BY seller_id\n)',
    brokenOutputNote: 'Returns 2.6. The subquery only includes sellers who appear in the transactions table with completed status. Sellers with zero completed transactions — including seller 6, who only has a refunded transaction — are completely absent from the GROUP BY result. The outer AVG divides total completed transactions by the count of sellers who transacted, not by the count of all registered sellers.',
    expectedColumns: ['avg_completed_txns'],
