      { text: 'Group the results by product to aggregate the order counts and ensure all products are represented, even those with zero orders.', starterCode: 'SELECT p.product_id, p.name, p.category, COUNT(oi.item_id) AS times_ordered\nFROM products p\nLEFT JOIN order_items oi ON p.product_id = oi.product_id\nGROUP BY p.product_id, p.name, p.category\n-- add ordering here' }
