    brokenQuery: 'SELECT strftime(\'%Y\', occurred_at) AS month, COUNT(*) AS login_count\nFROM events\nWHERE event_name = \'login\'\nGROUP BY strftime(\'%Y\', occurred_at)\nORDER BY month',
