    title: 'High-Risk Transaction Lookup — Subquery Returns Multiple Rows',
    company: 'Stripe',
    companyDomain: 'stripe.com',
    format: 'forensic',
    difficulty: 'Forensic',
    isFree: false,
    tags: ['forensic', 'subquery', 'scalar subquery', 'IN vs equals', 'SQL error'],
